/**
 * The boost-interior-demo PORTFOLIO DATASET as it stood on 2026-10-06 — FROZEN, TEST-ONLY.
 *
 * Until Portfolio Content System V1 the demo's portfolio (content/projects.json, content/categories.json,
 * the 44 portfolio images and their registry entries) was hand-authored, and the data-truth tests pinned
 * literal hashes of it straight from data/sites/boost-interior-demo. From now on that directory is
 * regenerated by site:portfolio-sync whenever the customer publishes in BoostChat, so its content
 * legitimately changes and a literal pin can no longer be read from it.
 *
 * platform/test/fixtures/boost-interior-demo-frozen holds that dataset verbatim (bi-01 … bi-08, the
 * production corpus since the 2026-09-29 record truth split). `frozenDemoRoot` composes it back into a
 * throwaway repository root:
 *
 *     the LIVE site directory (site.json, settings, slots, theme, scripts, inquiry, integration,
 *     banners, reviews, business, the site-level assets — everything the site itself owns, so a
 *     re-pin or a copy change still moves every literal exactly as before)
 *   + the FROZEN portfolio dataset in place of whatever portfolio the live directory holds now
 *
 * While the live directory is still hand-authored and unchanged, the composition is the live directory
 * byte for byte (`live.identical`), so every literal pin keeps describing the real site; once it is
 * managed, the pins keep describing the frozen dataset and the live directory is covered by the checks
 * that hold for any dataset (portfolio-production-truth.test.ts [live]).
 *
 * Since 2026-10-07 the demo is ADOPTED: its tracked marker portfolio.source.json is committed
 * (platform/portfolio-sync/managed.ts). The generated portfolio itself (portfolio.managed.json and the
 * files it lists) is produced in the publisher's checkout and never committed, so a development
 * checkout holds the marker and NO generated portfolio: there the live directory is not a dataset at
 * all — the loader, site:build and the manual site:publish refuse it (`live.dataset` = false). The
 * marker is not a snapshot input and the composition drops it, so nothing below changes: a test that
 * needs the demo as a buildable site (a literal pin, the tracked current package, or just "a real
 * site") reads it through `frozenDemoRoot` / `testSiteRoot`, and a [live] check runs only where the
 * live directory is a dataset — elsewhere it asserts the refusal (`NOT_GENERATED`).
 *
 * Imported by tests only. Nothing is ever written under data/sites.
 */
import { rmSync } from "node:fs";
import { cp, mkdir, mkdtemp, readFile, readdir, rm, symlink, writeFile } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { AssetRegistryDocSchema } from "../assets/assets";
import { MANAGED_FILE, SOURCE_MARKER_FILE, hasSourceMarker, readManagedManifest } from "../portfolio-sync/managed";
import { hashJson, sha256 } from "../util/hash";

export const FROZEN_DEMO_SITE_ID = "boost-interior-demo";
export const FROZEN_DEMO_DIR = "platform/test/fixtures/boost-interior-demo-frozen";
/** the fixture's own bytes, as literals: the frozen dataset can never drift unnoticed */
export const FROZEN_PROJECTS_SHA256 = "5331037230ae07a6167a4808e20557b7b2817081df5d4076d02b41b6a5fb7c83";
export const FROZEN_PROJECTS_BYTES = 28829;
export const FROZEN_CATEGORIES_SHA256 = "251f28b9f9d48ca77e16ae6989f2478979caa1dd9c7ef7e9bdd063fc4507fda5";
export const FROZEN_REGISTRY_SHA256 = "e9419831553a932089bacacaacb278b9c3172e87fec4447053b6dbd08d490771";
/** hashJson of [{ file, sha256 }] over the 44 image files, by file name */
export const FROZEN_ASSETS_DIGEST = "1443f135e7042051d36ed8379f45676e34c55d4f5369c58163482060e1f69a22";
export const FROZEN_ASSET_COUNT = 44;
/** what the loader says for an adopted site in a checkout that holds no generated portfolio (managed.ts) */
export const NOT_GENERATED = /owned by BoostChat \(portfolio\.source\.json\) but this checkout holds no generated portfolio \(portfolio\.managed\.json is missing\)[\s\S]*site:portfolio-sync --site boost-interior-demo/;

export interface FrozenDemoRoot {
  /** a repository-root-shaped throwaway directory: data/sites/<demo>, data/template-releases, node_modules */
  root: string;
  siteDir: string;
  live: {
    /** the live site directory carries the managed sidecar */
    managed: boolean;
    /** the live directory's portfolio dataset is byte-identical to the frozen one */
    identical: boolean;
    /** the live site directory carries the tracked adoption marker (portfolio.source.json) */
    adopted: boolean;
    /**
     * the live directory is a portfolio dataset this checkout may load and build: hand-authored and
     * not adopted, or generated (sidecar). false = adopted without a generated portfolio — its content
     * files may be older than what is live, and every loader path refuses it (NOT_GENERATED)
     */
    dataset: boolean;
  };
}

/** The frozen fixture, verified against its literals. */
export async function readFrozenDataset(repoRoot: string) {
  const dir = path.join(repoRoot, FROZEN_DEMO_DIR);
  const projects = await readFile(path.join(dir, "content/projects.json"));
  const categories = await readFile(path.join(dir, "content/categories.json"));
  const registryBytes = await readFile(path.join(dir, "assets/registry.json"));
  const registry = AssetRegistryDocSchema.parse(JSON.parse(registryBytes.toString("utf8")));
  const assets: { file: string; sha256: string; bytes: Buffer }[] = [];
  for (const file of (await readdir(path.join(dir, "assets"))).filter((f) => f !== "registry.json" && f !== ".DS_Store").sort()) {
    const bytes = await readFile(path.join(dir, "assets", file));
    assets.push({ file, sha256: sha256(bytes), bytes });
  }
  const facts = [sha256(projects), projects.length, sha256(categories), sha256(registryBytes), assets.length, hashJson(assets.map(({ file, sha256: s }) => ({ file, sha256: s })))];
  const literals = [FROZEN_PROJECTS_SHA256, FROZEN_PROJECTS_BYTES, FROZEN_CATEGORIES_SHA256, FROZEN_REGISTRY_SHA256, FROZEN_ASSET_COUNT, FROZEN_ASSETS_DIGEST];
  if (JSON.stringify(facts) !== JSON.stringify(literals)) throw new Error(`${FROZEN_DEMO_DIR} is not the frozen dataset any more: ${JSON.stringify(facts)} ≠ ${JSON.stringify(literals)}`);
  if (JSON.stringify(registry.items.map((a) => a.file).sort()) !== JSON.stringify(assets.map((a) => a.file))) throw new Error(`${FROZEN_DEMO_DIR}: registry entries ≠ image files`);
  return { dir, projects, categories, registry, assets };
}

export async function frozenDemoRoot(repoRoot: string): Promise<FrozenDemoRoot> {
  const frozen = await readFrozenDataset(repoRoot);
  const liveDir = path.join(repoRoot, "data/sites", FROZEN_DEMO_SITE_ID);
  const root = await mkdtemp(path.join(os.tmpdir(), "frozen-demo-root-"));
  process.once("exit", () => rmSync(root, { recursive: true, force: true }));
  await mkdir(path.join(root, "data/sites"), { recursive: true });
  await symlink(path.join(repoRoot, "data/template-releases"), path.join(root, "data/template-releases"));
  await symlink(path.join(repoRoot, "node_modules"), path.join(root, "node_modules"));
  const siteDir = path.join(root, "data/sites", FROZEN_DEMO_SITE_ID);
  await cp(liveDir, siteDir, { recursive: true });
  const adopted = await hasSourceMarker(liveDir);

  // 1. drop the portfolio the live directory holds now, when it is a generated one
  const managed = await readManagedManifest(siteDir);
  for (const a of managed?.assets ?? []) await rm(path.join(siteDir, "assets", a.file), { force: true });
  await rm(path.join(siteDir, MANAGED_FILE), { force: true });
  // the composition is a hand-authored site again: not adopted (an adopted site refuses to load without its sidecar)
  await rm(path.join(siteDir, SOURCE_MARKER_FILE), { force: true });
  const managedIds = new Set((managed?.assets ?? []).map((a) => a.id));

  // 2. the frozen dataset, verbatim; site-owned registry entries stay exactly as the live file has them
  const liveRegistry = AssetRegistryDocSchema.parse(JSON.parse(await readFile(path.join(liveDir, "assets/registry.json"), "utf8")));
  const same = async (rel: string, bytes: Buffer) => sha256(await readFile(path.join(liveDir, rel)).catch(() => Buffer.alloc(0))) === sha256(bytes);
  let identical = !managed && (await same("content/projects.json", frozen.projects)) && (await same("content/categories.json", frozen.categories));
  await writeFile(path.join(siteDir, "content/projects.json"), frozen.projects);
  await writeFile(path.join(siteDir, "content/categories.json"), frozen.categories);
  for (const a of frozen.assets) {
    identical &&= await same(`assets/${a.file}`, a.bytes);
    await writeFile(path.join(siteDir, "assets", a.file), a.bytes);
  }
  const frozenIds = new Set(frozen.registry.items.map((a) => a.id));
  const items = [...frozen.registry.items, ...liveRegistry.items.filter((a) => !managedIds.has(a.id) && !frozenIds.has(a.id))];
  const registrySame = JSON.stringify(items) === JSON.stringify(liveRegistry.items);
  identical &&= registrySame;
  if (!registrySame) await writeFile(path.join(siteDir, "assets/registry.json"), `${JSON.stringify({ schema: "assets@1", origin: liveRegistry.origin, items }, null, 2)}\n`);
  return { root, siteDir, live: { managed: managed !== undefined, identical, adopted, dataset: !adopted || managed !== undefined } };
}

/**
 * Where a test that needs site `siteId` as a BUILDABLE site reads it from: the repository itself for
 * every site but the demo, the frozen composition for the demo (the live demo directory is regenerated
 * by site:portfolio-sync, and in a checkout without a generated portfolio it does not load at all).
 * `root` holds data/sites/<siteId> and the template releases only — data/site-builds stays in `repoRoot`.
 */
export async function testSiteRoot(repoRoot: string, siteId: string): Promise<{ root: string; siteDir: string }> {
  if (siteId !== FROZEN_DEMO_SITE_ID) return { root: repoRoot, siteDir: path.join(repoRoot, "data/sites", siteId) };
  const { root, siteDir } = await frozenDemoRoot(repoRoot);
  return { root, siteDir };
}
